using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.BeardLichen;

/// <summary>
/// Beard lichen, pale strands that hang from dead branches in the Mistlands. Model: generated by
/// AssetSource/Tools/make_forage_models.py; the branch stays and the lichen grows back. Hares sometimes carry it in
/// their fur.
/// </summary>
public class BeardLichen : ForageableBase
{
    /// <summary>
    /// Prefab name of the beard lichen item.
    /// </summary>
    public const string PrefabName = "WhiteHiltBeardLichen";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Beard Lichen";

    /// <inheritdoc/>
    protected override string Description => "Pale grey-green strands that hang from dead branches in the mist. It keeps wounds clean, and in hungry winters it was ground into bread.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Thistle";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Mushroom";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 2,
        GroupRadius = 4f,
        MinAltitude = 1f,
        MaxTilt = 25f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override string CreatureDropFrom => "Hare";

    /// <inheritdoc/>
    protected override float CreatureDropChance => 0.15f;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.1f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "beardlichenitem", 0.1f);
    }

    /// <inheritdoc/>
    protected override void ApplyPickableVisual(GameObject pickablePrefab, Pickable pickable)
    {
        ReplaceBushMesh(pickablePrefab, pickable, "beardlichen", 0.35f);
    }
}
